const num = (v, key, { min = -1e12, max = 1e12, integer = false, allowZero = true } = {}) => {
  if (v?.[key] == null || String(v[key]).trim() === '') throw new Error(`${key} is required.`);
  const n = Number(v[key]);
  if (!Number.isFinite(n) || n < min || n > max || (!allowZero && n === 0) || (integer && !Number.isInteger(n))) {
    throw new Error(`${key} must be ${integer ? 'an integer' : 'a number'} from ${allowZero ? min : `above ${min}`} to ${max}.`);
  }
  return n;
};
const list = (v, key = 'values', { minLength = 1, maxLength = 500, integers = false } = {}) => {
  const a = String(v?.[key] ?? '').split(/[\s,;]+/).filter(Boolean).map(Number);
  if (a.length < minLength || a.length > maxLength || a.some(x => !Number.isFinite(x) || Math.abs(x) > 1e12 || (integers && !Number.isInteger(x)))) throw new Error(`${key} must contain ${minLength === 1 ? 'at least one' : `between ${minLength} and ${maxLength}`} valid ${integers ? 'integer' : 'number'}${integers ? 's' : 's'}, separated by commas or spaces.`);
  return a;
};
const f = (key, label, value = '', unit = '', extra = {}) => ({ key, label, type: 'number', value: String(value), unit, ...extra });
const t = (key, label, value = '', extra = {}) => ({ key, label, type: 'text', value: String(value), ...extra });
const sel = (key, label, value, options) => ({ key, label, type: 'select', value, options: options.map(([value, label]) => ({ value, label })) });
const res = (label, value, unit = '') => ({ value, unit, label, details: [] });
const checked = (x) => { if (!Number.isFinite(x) || Math.abs(x) > 1e100) throw new Error('The result is outside the supported numeric range.'); return x; };
const integerBig = (v,key,{min=-1000000000000n,max=1000000000000n,allowZero=true}={})=>{
  const raw=String(v?.[key]??'').trim();
  if(!/^[+-]?\d+$/.test(raw))throw new Error(`${key} must be a whole number written with digits.`);
  const x=BigInt(raw);
  if(x<min||x>max||(!allowZero&&x===0n))throw new Error(`${key} must be ${allowZero?'an integer':'a nonzero integer'} between ${min} and ${max}.`);
  return x;
};
const gcdBig=(a,b)=>{a=a<0n?-a:a;b=b<0n?-b:b;while(b)[a,b]=[b,a%b];return a;};
const descriptions = {
 'scientific-calculator':['Evaluate a mathematical expression with standard operator precedence, powers, roots, trigonometric functions, logarithms, and constants. This scientific calculator is useful for homework checks and engineering estimates when the expression is within JavaScript number precision.','Enter a concise expression using +, -, *, /, ^, parentheses, sqrt(), sin(), cos(), tan(), log(), ln(), abs(), pi, or e. Trigonometric functions use radians; exponentiation binds before multiplication.','For 2 * (3 + 4)^2, first add inside the parentheses to get 7, square it to get 49, then multiply by 2 to obtain 98.','Which angle unit is used? Radians are used for trigonometric functions.','Can it represent every decimal exactly? No. Results use floating-point arithmetic, so very large, tiny, or repeating values may be rounded.'],
 'fraction-calculator':['Add, subtract, multiply, or divide two signed fractions and return a reduced numerator and denominator. The result includes the decimal value so you can compare a fraction with a measurement or another representation.','Fractions are normalized by a greatest-common-divisor reduction. Addition and subtraction use a common denominator; multiplication multiplies corresponding terms; division multiplies by the reciprocal.','For 2/3 + 1/4, use denominator 12: 8/12 + 3/12 = 11/12.','Will the answer be reduced? Yes, numerator and denominator are divided by their greatest common divisor.','Can I divide by a zero fraction? No. A zero divisor is rejected because the quotient is undefined.'],
 'percent-calculator':['Solve the three common percentage questions: find a percentage of a number, determine what percent one amount is of another, or find the percentage change between two values. Each mode uses a clearly defined base to avoid confusing percentage points with percent change.','Choose the relationship you know. “P% of X” is X × P/100; “A is what percent of B” is A/B × 100; percent change is (new − old)/|old| × 100.','A price moving from 80 to 92 changes by (92−80)/80 × 100 = 15%.','What does a negative change mean? The new value is below the starting value; the signed result preserves that direction.','Why can percent change be undefined? A zero starting value cannot serve as the denominator.'],
 'triangle-calculator':['Find a triangle’s third side and area from two sides and their included angle. The calculator checks the angle and side lengths before applying the included-angle area relation and the cosine rule.','With sides a and b and included angle C, area = ab sin(C)/2 and c = √(a²+b²−2ab cos(C)). The entered angle is in degrees.','Sides 5 and 7 with an included 60° angle give area about 15.16 square units and third side √39 ≈ 6.245.','Does the angle have to be between 0° and 180°? Yes; a triangle’s interior angle must be strictly between those bounds.','What units does the area use? Squared versions of the side unit, so centimetres produce square centimetres.'],
 'volume-calculator':['Calculate volume for a cube, rectangular prism, cylinder, sphere, cone, or triangular prism. Select a shape and enter only its defining dimensions to get a result in cubic units.','The selected solid uses its standard geometric volume rule: for example cylinder πr²h, sphere 4πr³/3, cone πr²h/3, or prism base area multiplied by length.','A cylinder with radius 3 cm and height 8 cm has volume π × 3² × 8 ≈ 226.19 cm³.','Should radius or diameter be entered? Enter radius for circular shapes; if you know diameter, divide it by two first.','What assumptions apply to a triangular prism? Its base is a triangle with the two supplied perpendicular legs.'],
 'standard-deviation-calculator':['Measure the spread of a numeric dataset with either population or sample standard deviation. The output also reports mean and variance so you can see both the dataset’s center and the squared spread used in the calculation.','Population deviation divides the sum of squared deviations from the mean by n. Sample deviation divides by n−1, applying Bessel’s correction when the list represents a sample.','For 2, 4, 6, the mean is 4; population SD is √(8/3) ≈ 1.633, while sample SD is 2.','Which choice should I use for a sample? Choose sample when these observations estimate a wider population.','Why does sample mode require two values? With one observation, n−1 is zero and sample variance cannot be estimated.'],
'random-number-generator':['Generate a batch of random numbers within a range you choose, using integer or decimal mode and a bounded quantity. Integer draws use cryptographically secure rejection sampling for a uniform inclusive range, making the results suitable for general random selection and software testing.','Integer mode samples from every whole number between the entered minimum and maximum, including both endpoints; rejection sampling avoids modulo bias. Decimal mode uses secure random bits to produce values from the minimum up to, but not including, the maximum. The browser or runtime must provide the Web Crypto random generator.','With integer mode, range 1 to 6, and quantity 4, the tool returns four independent whole-number draws such as 2, 6, 1, and 4.','Are the integer endpoints included? Yes. Integer mode includes both the minimum and maximum; decimal mode excludes the maximum.','Can I use these numbers for passwords or encryption keys? No. Although draws use Web Crypto, a general-purpose calculator is not a key-management or security workflow.'],
 'number-sequence-calculator':['Inspect an ordered list for a constant arithmetic difference or constant geometric ratio, then extend the sequence by one term. It also reports the observed step pattern so a simple sequence can be checked without guessing its rule.','For an arithmetic sequence, the next term is last + d where d is the repeated difference. For a geometric sequence, it is last × r where r is the repeated ratio.','The sequence 3, 7, 11 has a repeated difference of 4, so its next term is 15.','Can every sequence be uniquely continued? No. Many rules can fit the same finite list; this tool tests only arithmetic and geometric patterns.','What if the differences and ratios are both inconsistent? The calculator reports that neither supported pattern fits.'],
 'percent-error-calculator':['Compare an observed measurement with an accepted reference and express the absolute discrepancy as a percentage of the reference. Signed error and absolute error are shown separately, which helps distinguish direction from magnitude.','Signed percent error = (observed − reference)/reference × 100. Absolute percent error uses the absolute value of that signed percentage.','If a measured length is 9.8 and the accepted value is 10, signed error is −2% and absolute error is 2%.','Why enter the accepted value as nonzero? It is the denominator that defines relative error.','Does a negative signed result mean the measurement is wrong? It indicates the observed value is below the reference; magnitude is captured by absolute error.'],
 'exponent-calculator':['Raise a real base to a real exponent and inspect the power, including common integer, fractional, and negative powers. The validation catches undefined real-number cases such as zero to a negative exponent or a negative base with a non-integer exponent.','For a nonzero base, a negative exponent means the reciprocal of the corresponding positive power: a^(−n)=1/a^n. Fractional exponents are evaluated over real numbers only when the result is real.','2^−3 = 1/2³ = 1/8 = 0.125.','Why reject a negative base with a decimal exponent? That power may be complex, while this calculator returns real numbers only.','What is 0 to a negative power? It is undefined because it would require division by zero.'],
 'binary-calculator':['Perform addition, subtraction, multiplication, or division on two binary integers and show the result in base 2 and base 10. Inputs are parsed as bit strings, so leading zeros are allowed and do not change the represented value.','Each binary string is converted to an integer, the selected arithmetic operation is applied, and the result is converted back to base 2. Division is integer quotient with remainder.','1011₂ is 11₁₀; adding 101₂ (5) gives 10000₂ (16).','Can I use digits 2 through 9? No. Binary notation contains only 0 and 1.','How is division represented? The result includes the whole-number quotient and the remainder.'],
 'hex-calculator':['Add, subtract, multiply, or divide two hexadecimal integers using digits 0–9 and A–F. Results are returned in hexadecimal and decimal, making it easier to verify address arithmetic, bit-level examples, and number-system conversions.','The operands are parsed in base 16, the chosen integer operation is performed, and the result is converted back to uppercase hexadecimal. Division returns an integer quotient and remainder.','0x2A + 0x10 = 0x3A, because 42 + 16 = 58 in decimal.','Are lowercase letters accepted? Yes; hexadecimal input is case-insensitive.','What does division do with a remainder? It reports the integer quotient and remainder rather than a rounded decimal.'],
 'half-life-calculator':['Estimate the remaining quantity of a decaying substance after a specified number of half-lives. Enter the initial amount, half-life duration, and elapsed time to see the remaining quantity and fraction left under an ideal exponential-decay model.','Remaining amount = initial amount × (1/2)^(elapsed time / half-life). This continuous model works for any nonnegative elapsed duration; it does not predict individual decay events.','After three half-lives, 80 mg becomes 80 × (1/2)³ = 10 mg.','Does one half-life mean all material disappears? No. It means the expected quantity is reduced by half.','Does the output account for environmental conditions? No; it assumes the supplied half-life is constant and the system is not replenished.'],
 'quadratic-formula-calculator':['Solve a quadratic equation ax² + bx + c = 0, reporting real roots or a complex conjugate pair and the discriminant. This makes the sign of the discriminant visible alongside the solutions.','The discriminant is D=b²−4ac and roots are (−b ± √D)/(2a). If D is negative, √D is represented as an imaginary component. When D is zero, both solutions coincide at one repeated root; the denominator 2a also explains why a cannot be zero.','For x²−5x+6=0, D=1 and the roots are 2 and 3.','May a be zero? No. With a=0 the equation is linear, not quadratic.','What does a negative discriminant indicate? There are no real roots; the two roots are complex conjugates.'],
 'slope-calculator':['Find the slope and line equation through two coordinate points. It identifies vertical lines separately because their slope is undefined, while still giving their equation.','For distinct x-coordinates, slope m=(y₂−y₁)/(x₂−x₁), and point-slope form yields y=mx+b. When x₁=x₂, the line is vertical and has equation x=x₁.','Points (1, 2) and (4, 8) produce slope 2 and line y=2x.','Do the points need to be different? Yes; identical points do not determine a unique line.','What happens with a vertical line? The tool reports an undefined slope and its constant-x equation.'],
 'log-calculator':['Evaluate log base b of a positive number x, answering the question b raised to what power gives x. The base is checked against the logarithm’s domain, and the change-of-base relation is shown for verification.','log_b(x)=ln(x)/ln(b), requiring x>0, b>0, and b≠1. The logarithm is the inverse of exponentiation: its answer y must satisfy b^y=x. The change-of-base relation permits any valid base to be evaluated with natural logarithms.','log₂(32)=5 because 2⁵=32.','Can the base be 1? No; powers of 1 never distinguish positive inputs.','Can the input be zero or negative? Real logarithms are defined only for positive arguments.'],
 'area-calculator':['Calculate area for a rectangle, triangle, circle, or trapezoid from the dimensions each shape requires. The selected formula and squared unit keep the geometry clear, whether checking a room plan or a classroom exercise.','Rectangle area is lw; triangle area is bh/2; circle area is πr²; trapezoid area is (a+b)h/2 for parallel sides a and b. For the trapezoid, h is the perpendicular distance between its parallel sides, not the sloping side. Use matching length units throughout so the result is consistently in square metres, square centimetres, or another squared unit.','A 4 m by 6 m rectangle has area 24 m².','Do I enter a circle’s diameter? Enter its radius.','Why is area measured in square units? Multiplying two lengths creates a squared unit such as cm².'],
 'sample-size-calculator':['Estimate a survey sample size for a population proportion using a confidence level, margin of error, expected proportion, and optional finite-population correction. The result is rounded up because a partial respondent cannot satisfy the requested precision.','The large-population estimate is n₀=z²p(1−p)/e². For finite population N, apply n=n₀/[1+(n₀−1)/N]. The method assumes a simple random sample and a proportion outcome.','At 95% confidence, 5% margin, and p=0.5, a large population needs about 385 responses.','Why is 50% the default proportion? It maximizes p(1−p), producing a conservative largest sample estimate when the true share is unknown.','Does this guarantee a representative sample? No; nonresponse and sampling design can introduce bias that the formula does not remove.'],
 'probability-calculator':['Compute a binomial probability for exactly, at most, or at least k successes in n independent trials with the same success probability. It also reports the expected number of successes, so the event probability has useful context.','For X~Binomial(n,p), P(X=k)=C(n,k)p^k(1−p)^(n−k). Cumulative options sum the relevant outcomes from 0 through n. “At most k” includes zero through k; “at least k” includes k through n. The model describes a fixed number of independent trials with one shared success chance, such as repeated draws with replacement or repeated fair coin flips.','With 5 fair coin flips, exactly 2 heads has probability C(5,2)/2⁵=10/32=31.25%.','What assumptions does the binomial model make? A fixed trial count, independent trials, and a constant success probability.','Does “at least” include the chosen count? Yes, it sums k through n.'],
 'statistics-calculator':['Summarize a list of measurements with count, mean, median, mode, range, sample standard deviation, and quartiles. This broad statistics calculator is suited to a quick descriptive check before choosing a more specialized statistical method.','Mean is sum/n; median is the center of the sorted values; range is max−min. Quartiles use the median-of-halves convention, excluding the overall median for odd-sized lists.','For 1, 2, 2, 5, the mean is 2.5, median is 2, mode is 2, and range is 4.','How are tied modes shown? Every value with the highest frequency is listed.','Does this perform an inferential test? No; it summarizes the entered observations and does not account for study design.'],
 'mean-median-mode-range-calculator':['Find the four familiar summaries of a dataset: arithmetic mean, median, mode, and range. The sorted input and tie handling make it easy to spot outliers or repeated values before interpreting the numbers.','The mean adds all observations and divides by the count; the median is the middle sorted observation (or midpoint of two middles); mode is the most frequent value; range is maximum minus minimum.','For 2, 3, 3, 8, the mean is 4, median is 3, mode is 3, and range is 6.','Can there be multiple modes? Yes. All values tied for greatest frequency are returned.','What if every value appears once? The data have no mode, which is reported explicitly.'],
 'permutation-and-combination-calculator':['Count ordered arrangements or unordered selections from n distinct items taken r at a time. Choose permutations when order matters and combinations when only membership matters, with integer and range checks for both counts.','Permutation P(n,r)=n!/(n−r)!; combination C(n,r)=n!/[r!(n−r)!]. The calculation uses exact BigInt arithmetic before rendering the count.','Selecting a president and vice president from 5 people gives P(5,2)=20 ordered assignments; choosing 2 committee members gives C(5,2)=10.','What is the difference between the modes? Permutations distinguish different orders; combinations treat the same selected group as one outcome.','Can r exceed n? No, a selection cannot contain more distinct items than are available.'],
 'z-score-calculator':['Convert an observation into standard-deviation units from a distribution’s mean. A positive z-score is above the mean, a negative score is below it, and zero is exactly at the mean.','z=(x−μ)/σ, where σ is a positive population standard deviation. The result is a distance in standard-deviation units, not a probability by itself.','A value of 70 in a distribution with mean 60 and SD 5 has z=(70−60)/5=2.','Does z=2 always mean a 97.7th percentile? Only under a normal-distribution assumption; the score alone does not establish a distribution shape.','Why must standard deviation be positive? A zero spread makes division by σ undefined.'],
 'confidence-interval-calculator':['Build a two-sided confidence interval for a population mean from a sample mean, sample standard deviation, sample size, and confidence level. It uses Student’s t critical value, which accounts for the extra uncertainty from estimating population spread.','Interval = x̄ ± t* s/√n with n−1 degrees of freedom. The t critical value is numerically evaluated from the selected confidence level.','For mean 50, SD 10, n=25, a 95% interval is approximately 50 ± 4.13, or 45.87 to 54.13.','Does 95% mean this particular interval has a 95% chance of containing the mean? In repeated sampling, 95% of intervals constructed this way would contain the true mean under the assumptions.','What assumptions matter? Independent observations and a reasonably suitable sampling distribution; small samples require particular care with skew and outliers.'],
 'ratio-calculator':['Reduce a two-part ratio to its simplest whole-number terms and scale it to a requested total. Decimal inputs are converted to a practical common integer scale before the greatest common factor is removed.','For positive parts a:b, divide both by gcd(a,b). Given a total T, the first share is T×a/(a+b) and the second is T×b/(a+b).','A 2:3 mixture totaling 20 units contains 8 units of the first part and 12 of the second.','Does 2:3 mean two divided by three? It describes relative quantities; its value as a fraction is 2/3.','Can one part be zero? Yes; the output still describes the resulting split, provided both parts are not zero.'],
 'distance-calculator':['Measure straight-line distance between two points in a plane or in three-dimensional coordinates. The coordinate differences and Euclidean distance are returned so the geometry behind the result remains easy to inspect.','2D distance is √[(x₂−x₁)²+(y₂−y₁)²]. For 3D, add the squared z-coordinate difference under the same square root. This is the shortest straight segment between the entered coordinates, so it does not account for roads, terrain, or travel routes. Coordinate units carry through unchanged: points measured in metres produce a distance in metres.','Between (1,2) and (4,6), the distance is √(3²+4²)=5 units.','Does this calculate road distance? No; it measures straight-line coordinate distance.','Can coordinates be negative? Yes, any finite coordinates are valid.'],
 'circle-calculator':['Derive a circle’s radius, diameter, circumference, and area from one known measurement. Select the input type so the calculator applies the correct relationship instead of treating a diameter as a radius.','The circle relations are d=2r, circumference=2πr, and area=πr². If circumference or area is entered, radius is recovered before the other values are calculated.','A circle with diameter 10 cm has circumference 10π ≈ 31.416 cm and area 25π ≈ 78.540 cm².','May a circumference or area be zero? No; a zero-size circle has no positive radius.','Why is area in squared units while circumference is in ordinary units? Area spans two dimensions; circumference measures a length around the boundary.'],
 'surface-area-calculator':['Find the total outside area of a cube, rectangular box, sphere, cylinder, cone, or square pyramid. Enter the dimensions for the selected solid to distinguish lateral area from the full area including bases.','The formulas include 6a² for a cube, 2(lw+lh+wh) for a box, 4πr² for a sphere, and 2πr²+2πrh for a closed cylinder. Cone and pyramid calculations use slant height.','A closed cylinder with r=2 and h=5 has surface area 2π(2²)+2π(2)(5)=28π ≈ 87.96 square units.','Is cylinder area for an open or closed cylinder? It is the total for a closed cylinder, including both circular ends.','What is slant height? It is the straight distance along the sloped side from the apex to the base edge.'],
 'pythagorean-theorem-calculator':['Solve a right triangle when two side lengths are known, identifying the hypotenuse when needed. The tool checks whether the supplied pair can form a right triangle and reports the missing side together with the verification relation.','For legs a and b, c=√(a²+b²). If hypotenuse c and leg a are known, the remaining leg is √(c²−a²), requiring c>a. The hypotenuse is opposite the right angle and is always the longest side; checking this ordering prevents taking the square root of a negative value.','Legs 3 and 4 yield hypotenuse √(9+16)=5.','Can the hypotenuse be shorter than a leg? No; it is the longest side of a right triangle.','Are inputs side lengths or coordinates? Enter positive side lengths; coordinate geometry uses the distance calculator.'],
 'right-triangle-calculator':['Complete a right triangle from two known measurements, such as two legs or a leg and an acute angle. The answer includes both acute angles and the hypotenuse, using degrees for angle inputs.','The acute angles sum to 90°. Side ratios follow sine, cosine, and tangent; with legs a,b, hypotenuse c=√(a²+b²). In the side-angle mode, the given leg is treated as opposite the entered angle; the second leg and hypotenuse are derived from the trigonometric ratios.','A 3-4-5 right triangle has acute angles about 36.87° and 53.13°.','Can both entered angles be acute angles? This tool accepts one acute angle plus a side or two sides, not two redundant angles.','What if I enter a side and its opposite angle? Select the supported side-angle mode and ensure the angle is between 0° and 90°.'],
 'root-calculator':['Find the principal nth root of a real number, including odd roots of negative values. The index must be a positive integer, and even roots of negative radicands are rejected because they are not real.','The nth root r satisfies rⁿ=x. For even n, x must be nonnegative; for odd n, the real root keeps the sign of x. For an even index there are two signed solutions to rⁿ=x when x is positive, but the principal root returned here is the nonnegative one.','The cube root of −125 is −5 because (−5)³=−125.','What does principal root mean for an even index? It is the nonnegative root.','Can the root index be zero? No; a zero index does not define a root operation.'],
 'lcm-calculator':['Find the least common multiple of two positive integers, the smallest positive number divisible by both. The result is useful for aligning repeating cycles and finding a common denominator for whole-number fractions.','For positive integers a and b, lcm(a,b)=a×b/gcd(a,b). Euclid’s algorithm finds the greatest common divisor efficiently.','The least common multiple of 12 and 18 is 36, the first positive multiple shared by both.','Can negative integers be entered? The calculator accepts nonzero integers and uses their absolute values.','What is the LCM of identical integers? Their absolute value.'],
 'gcf-calculator':['Find the greatest common factor (greatest common divisor) shared by two integers. The result can reduce fractions, simplify ratios, or identify the largest equal grouping that divides both quantities evenly.','Euclid’s algorithm repeatedly replaces (a,b) with (b,a mod b) until the remainder is zero; the last nonzero value is the greatest common factor.','For 84 and 30, gcd(84,30)=6, so both numbers are divisible by 6 and no larger common divisor exists.','Can one input be zero? Yes, gcd(a,0)=|a| when a is nonzero.','Why reject two zeroes? Every positive integer divides zero, so there is no greatest finite common factor.'],
 'factor-calculator':['List all positive factor pairs of a positive integer and identify its prime or composite status. Seeing the pairs gives a practical way to check divisibility and understand how the integer can be built from smaller whole numbers.','A factor pair (d,n/d) is recorded whenever d divides n exactly. Trial divisors are checked only through √n, since larger partners have already appeared.','For 36, the factor pairs are 1×36, 2×18, 3×12, 4×9, and 6×6.','Is 1 a prime number? No; a prime has exactly two positive divisors, 1 and itself.','What is the largest input? Inputs are capped at 100,000,000 to keep listing factor pairs responsive.'],
 'rounding-calculator':['Round a decimal number to a chosen number of decimal places or significant figures. The result follows the common half-up rule for magnitude, while preserving a clear indication of the selected precision.','For decimal places, scale by 10^d, round the magnitude at the halfway point upward, then restore the sign. Significant-figure mode derives the decimal place from the value’s order of magnitude.','Rounding 12.345 to two decimal places gives 12.35.','Can decimal places be negative? Yes; −1 rounds to tens, −2 to hundreds.','How is an exact tie treated? Halfway cases round away from zero.'],
 'matrix-calculator':['Add, subtract, or multiply two small matrices and show the resulting matrix with compatible dimensions. This matrix calculator validates row lengths and multiplication shape before computing, so an invalid operation is explained rather than silently truncated.','Addition and subtraction are element-wise and require equal dimensions. Multiplication uses Cᵢⱼ=ΣₖAᵢₖBₖⱼ, requiring columns of A to match rows of B. Matrix multiplication is order-sensitive, so reversing A and B can change both the dimensions and the result; the entered A×B order is preserved.','[[1,2],[3,4]] × [[2,0],[1,2]] = [[4,4],[10,8]].','Can rectangular matrices be multiplied? Yes, if the first matrix’s column count matches the second matrix’s row count.','What size is supported? Each matrix may have up to 5 rows and 5 columns.'],
 'scientific-notation-calculator':['Convert a finite decimal to normalized scientific notation or turn a coefficient and exponent into its ordinary decimal value. Normalized notation keeps one nonzero digit before the decimal point and makes powers of ten easier to compare.','A nonzero value is expressed as m×10^e where 1≤|m|<10. Conversion back multiplies the coefficient by 10^e. The exponent therefore records how many places the decimal point moves, making very large and very small magnitudes easier to read without changing the value.','0.00072 becomes 7.2×10⁻⁴.','Can the coefficient be negative? Yes; the sign remains on the coefficient while its magnitude is normalized.','What happens to zero? Zero has no unique normalized exponent, so it is represented as 0.'],
 'big-number-calculator':['Add, subtract, multiply, or divide large whole numbers without losing integer precision to floating-point rounding. Inputs are parsed as decimal integers and results are returned exactly, subject to a practical digit limit.','The operation uses arbitrary-precision integer arithmetic. Division reports quotient and remainder because two integers do not always divide evenly.','12345678901234567890 + 10 is exactly 12345678901234567900.','Can I enter a decimal? No; this tool is for integers.','Why limit input length? A 200-digit cap protects the browser from oversized inputs while covering very large everyday integer calculations.'],
 'prime-factorization-calculator':['Express a positive integer as a product of prime powers and list the prime factors with multiplicity. The factorization is canonical, so it can also support divisor counting and simplification work.','Repeatedly divide by the smallest candidate prime until it no longer divides the remaining value; continue until the remainder itself is prime. The fundamental theorem of arithmetic guarantees that every integer greater than 1 has one unique prime factorization apart from factor order.','360 factors as 2³ × 3² × 5.','What is the factorization of 1? It has no prime factors; 1 is the multiplicative identity, not a prime.','How large an integer can I factor? Inputs are capped at 100,000,000 to keep trial division responsive.'],
 'common-factor-calculator':['List the positive common factors shared by two integers and show their greatest common factor. This makes the full shared divisor set visible instead of returning only the largest simplification factor.','The shared factors are the positive divisors of gcd(|a|,|b|). Euclid’s algorithm finds the gcd, after which its divisor pairs enumerate the common set.','For 18 and 24, the common factors are 1, 2, 3, and 6; the greatest is 6.','Can values be negative? Yes; divisibility uses absolute values.','Can both values be zero? No; that would produce an unbounded set of common divisors.'],
 'basic-calculator':['Evaluate a basic arithmetic expression with parentheses and standard precedence for addition, subtraction, multiplication, and division. The parser rejects unsupported characters and malformed expressions rather than executing arbitrary code.','Multiplication and division are evaluated before addition and subtraction; parentheses override precedence. Unary signs and decimal literals are supported.','For (18 + 6) / 3 − 2, parentheses give 24, division gives 8, and the result is 6.','Can I use powers or functions? This basic mode supports only arithmetic operators and parentheses.','Is my expression executed as code? No; a restricted arithmetic parser reads only numeric tokens and operators.'],
 'long-division-calculator':['Divide one signed integer by another and show the integer quotient, remainder, and decimal quotient. The remainder follows the dividend’s sign, matching truncation toward zero.','For integers a and b≠0, quotient q=trunc(a/b) and remainder r=a−qb, so a=bq+r. This convention truncates the decimal quotient toward zero; some school methods instead use a nonnegative remainder, so the sign convention matters when either input is negative.','Dividing 17 by 5 gives quotient 3, remainder 2, and decimal result 3.4.','Can the divisor be zero? No; division by zero is undefined.','Why can a negative dividend have a negative remainder? The identity a=bq+r is maintained using a quotient truncated toward zero.'],
 'average-calculator':['Calculate the arithmetic average of a list of measurements and show the count and total used. The mean is a useful central summary when values are on the same scale and each observation should receive equal weight.','Arithmetic mean = (x₁+x₂+…+xₙ)/n. Every entered value contributes once, regardless of its size. Because extreme observations pull the mean toward themselves, compare it with the median when the list is skewed or contains outliers.','For 4, 7, and 10, the total is 21 and the average is 21/3=7.','Is average always the best summary? No; strong outliers can pull the mean away from a typical observation.','How many values are accepted? Enter between 1 and 500 finite values separated by commas or spaces.'],
 'p-value-calculator':['Convert a z statistic to a left-tailed, right-tailed, or two-tailed normal-theory p-value. The output is a tail area under the standard normal distribution and must be interpreted with the test design and assumptions.','For standard normal Z, left tail is Φ(z), right tail is 1−Φ(z), and two-tail is 2[1−Φ(|z|)]. A numerical approximation evaluates Φ. The p-value is conditional on the null model and chosen tail direction; it is neither the probability that the null is true nor a measure of effect size.','A z score of 1.96 gives a two-sided p-value of about 0.05.','Does a small p-value prove the hypothesis is true? No; it measures how unusual the statistic would be under a specified null model.','Can this replace a t-test or exact test? No; it accepts a z statistic and standard normal reference only.']
};
